# Villa 2 doors and windows. DATA = dict(phase, doors=[{id,x,y,width_u,wall,w_mm?,h_mm?}], windows=[{..., sill_mm, h_mm}])
# Openings are placed in the wall identified by its Mark (e.g. "G11"), at DWG coordinates. Types are duplicated from the
# project's generic M_Single-Flush / M_Fixed families and sized by parameters. Verified by the host wall losing volume.
PH = DATA["phase"]
if DATA.get("purge", True): say("purged %d earlier %s elements" % (purge(PH), PH))
import Autodesk.Revit.DB.Structure as Structure
# Villa 2: arched window / door families, generated by editing the project's own generic families.
# For every spec the family M_Fixed (windows) or M_Single-Flush (doors) is opened with EditFamily, its geometry is replaced
# by: a void extrusion with the arch profile (cuts the wall), a frame ring and a glass pane (or door leaves), and the result
# is loaded back into the project under the spec's name. No template files are needed.
# DATA = dict(specs=[{name, kind: 'window'|'door', w, h, shape: rect|round|segmental|horseshoe, rise, frame, inset, leaves}])  metres.
import math
import System

def arch_loops(w, h, shape, rise=0.0, d=0.0, off=0.0):
    """Closed loop in (x, z) metres: bottom centre at z=0. Returns list of ('L', p, q) / ('A', p, mid, q) segments."""
    hw = w / 2.0 - off
    top = h - off
    segs = []
    z0 = off
    if shape == "rect":
        pts = [(-hw, z0), (hw, z0), (hw, top), (-hw, top)]
        for i in range(4): segs.append(("L", pts[i], pts[(i + 1) % 4]))
        return segs
    if shape == "segmental":
        spring = top - rise
        mid = (0.0, top)
        segs += [("L", (-hw, z0), (hw, z0)), ("L", (hw, z0), (hw, spring)), ("A", (hw, spring), mid, (-hw, spring)), ("L", (-hw, spring), (-hw, z0))]
        return segs
    if shape == "round":
        spring = top - hw
        segs += [("L", (-hw, z0), (hw, z0)), ("L", (hw, z0), (hw, spring)), ("A", (hw, spring), (0.0, spring + hw), (-hw, spring)), ("L", (-hw, spring), (-hw, z0))]
        return segs
    if shape == "horseshoe":
        rho = math.sqrt(hw * hw + d * d)
        spring = top - (d + rho)
        # the arc is more than a half circle: three points on it are the two spring points and the apex
        segs += [("L", (-hw, z0), (hw, z0)), ("L", (hw, z0), (hw, spring)), ("A", (hw, spring), (0.0, top), (-hw, spring)), ("L", (-hw, spring), (-hw, z0))]
        return segs
    raise Exception("unknown shape " + shape)

def to_curveloop(segs, y):
    cl = CurveLoop()
    for s in segs:
        if s[0] == "L":
            a, b = s[1], s[2]
            cl.Append(Line.CreateBound(XYZ(a[0] / FT, y / FT, a[1] / FT), XYZ(b[0] / FT, y / FT, b[1] / FT)))
        else:
            a, m, b = s[1], s[2], s[3]
            cl.Append(Arc.Create(XYZ(a[0] / FT, y / FT, a[1] / FT), XYZ(b[0] / FT, y / FT, b[1] / FT), XYZ(m[0] / FT, y / FT, m[1] / FT)))
    return cl

def build_family(fd, spec):
    """Replace the geometry inside the opened family document fd."""
    # remove old solids / voids / openings
    kill = []
    for e in FilteredElementCollector(fd).WhereElementIsNotElementType():
        if isinstance(e, GenericForm) or (e.Category is not None and e.Category.Name == "Opening cut"):
            kill.append(e.Id)
    for i in kill:
        try: fd.Delete(i)
        except: pass
    fd.Regenerate()
    # work plane: the wall centre plane (Center (Front/Back)) is the XZ plane at y = 0
    plane = Plane.CreateByNormalAndOrigin(XYZ.BasisY, XYZ.Zero)
    sp = SketchPlane.Create(fd, plane)
    fm = fd.FamilyManager
    def fam_mat(name, rgb, transp=0):
        for m in FilteredElementCollector(fd).OfClass(Material):
            if m.Name == name: return m.Id
        mid = Material.Create(fd, name); m = fd.GetElement(mid); m.Color = Color(*rgb)
        if transp: m.Transparency = transp
        return mid
    M_GLASS = fam_mat("AMB2_Glass", (190, 215, 225), 60); M_FRAME = fam_mat("AMB2_Frame", (70, 58, 50)); M_LEAF = fam_mat("AMB2_Timber", (110, 72, 44))
    cat = fd.OwnerFamily.FamilyCategory
    def subcat(name):
        try: return cat.SubCategories.get_Item(name)
        except: return None
    def style(ex, mat, sub):
        try: ex.get_Parameter(BuiltInParameter.MATERIAL_ID_PARAM).Set(mat)
        except Exception as e: pass
        sc = subcat(sub)
        if sc is not None:
            try: ex.Subcategory = sc
            except Exception as e: pass
    w, h, shape = spec["w"], spec["h"], spec["shape"]
    # The family's own Width/Height must equal the geometry (project-side edits would otherwise rescale it), and a window's
    # geometry has to start at the family's sill reference plane, because the instance is placed with origin = sill - default sill.
    zoff = 0.0
    try:
        pw, ph = fm.get_Parameter("Width"), fm.get_Parameter("Height")
        if pw is not None: fm.Set(pw, w / FT)
        if ph is not None: fm.Set(ph, h / FT)
        fd.Regenerate()
        if spec["kind"] == "window":
            ps = fm.get_Parameter("Default Sill Height")
            zoff = fm.CurrentType.AsDouble(ps) * FT if ps is not None else 0.0
    except Exception as e:
        zoff = 0.915 if spec["kind"] == "window" else 0.0
    # keep one type only, named like the family
    try:
        cur = fm.CurrentType
        for tt in list(fm.Types):
            if tt.Name != cur.Name:
                fm.CurrentType = tt; fm.DeleteCurrentType()
        fm.CurrentType = cur if cur is not None else fm.Types.get_Item(0)
        fm.RenameCurrentType(spec["name"])
    except Exception as e:
        pass
    rise = spec.get("rise", 0.0); d = spec.get("d", 0.12 * w)
    depth = spec.get("depth", 0.30)                       # wall thickness cut by the void
    def extrude(loops, y0, y1, solid, subcat=None):
        arr = CurveArrArray()
        for cl in loops:
            ca = CurveArray()
            for c in cl: ca.Append(c)
            arr.Append(ca)
        ex = fd.FamilyCreate.NewExtrusion(solid, arr, sp, (y1 - y0) / FT)
        ex.StartOffset = y0 / FT; ex.EndOffset = y1 / FT
        return ex
    def segs_to_curves(segs):
        out = []
        for s in segs:
            if s[0] == "L":
                a, b = s[1], s[2]; out.append(Line.CreateBound(XYZ(a[0] / FT, 0, (a[1] + zoff) / FT), XYZ(b[0] / FT, 0, (b[1] + zoff) / FT)))
            else:
                a, m, b = s[1], s[2], s[3]; out.append(Arc.Create(XYZ(a[0] / FT, 0, (a[1] + zoff) / FT), XYZ(b[0] / FT, 0, (b[1] + zoff) / FT), XYZ(m[0] / FT, 0, (m[1] + zoff) / FT)))
        return out
    outer = arch_loops(w, h, shape, rise, d, 0.0)
    # void that cuts the wall
    f = spec.get("frame", 0.06)
    inner = arch_loops(w, h, shape, rise, d, f)
    inset = spec.get("inset", 0.04)
    # frame ring = outer loop + inner loop (a hole)
    style(extrude([segs_to_curves(outer), segs_to_curves(inner)], -0.07 + inset, 0.07 + inset, True), M_FRAME, "Frame/Mullion")
    if spec["kind"] == "window":
        style(extrude([segs_to_curves(inner)], -0.01 + inset, 0.01 + inset, True), M_GLASS, "Glass")
    else:
        # door: two timber leaves up to the leaf height, glazed fanlight above (if the opening is taller than the leaves)
        lh = min(spec.get("leaf_h", h), h - f)
        leaves = [(-w / 2 + f, -0.01, 0.0, -0.0), (0.01, w / 2 - f, 0.0, 0.0)]
        for (x0, x1, _a, _b) in leaves:
            ring = [("L", (x0, f), (x1, f)), ("L", (x1, f), (x1, lh)), ("L", (x1, lh), (x0, lh)), ("L", (x0, lh), (x0, f))]
            style(extrude([segs_to_curves(ring)], -0.02 + inset, 0.02 + inset, True), M_LEAF, "Panel")
        if h - f > lh + 0.05:
            # fanlight: the arch profile above the leaf line
            top = arch_loops(w, h, shape, rise, d, f)
            fan = [s for s in top]
            # clip: rebuild as polygon-with-arch above lh by intersecting with a box is not available in the API, so use the full inner profile as glass behind the leaves
            style(extrude([segs_to_curves(inner)], -0.012 + inset, 0.012 + inset, True), M_GLASS, "Glass")

def make_family(spec):
    base = "M_Fixed" if spec["kind"] == "window" else "M_Single-Flush"
    fam = [f for f in FilteredElementCollector(doc).OfClass(Family) if f.Name == base][0]
    fd = doc.EditFamily(fam)
    try:
        t = Transaction(fd, "AMB2: arch family " + spec["name"]); t.Start()
        try:
            build_family(fd, spec)
            t.Commit()
        except Exception as e:
            t.RollBack(); raise
        class Opt(IFamilyLoadOptions):
            def OnFamilyFound(self, inUse, overwrite): return True
            def OnSharedFamilyFound(self, shared, inUse, source, overwrite): return True
        so = SaveAsOptions(); so.OverwriteExistingFile = True
        fd.SaveAs(System.IO.Path.Combine(System.IO.Path.GetTempPath(), spec["name"] + ".rfa"), so)
        fam2 = fd.LoadFamily(doc, Opt())
        return fam2
    finally:
        fd.Close(False)


def make_void_family(spec):
    """A Generic Model family that contains only a void extrusion with the arch profile. A project instance of it cuts any wall
    via InstanceVoidCutUtils.AddInstanceVoidCut. (A family Opening / void form inside a door or window family did NOT cut the
    host for arch profiles - measured with rays.) The profile runs from z=0 (sill) to z=h; depth is along the family Y axis."""
    base = [f for f in FilteredElementCollector(doc).OfClass(Family) if f.Name == "Pole"][0]
    fd = doc.EditFamily(base)
    try:
        t = Transaction(fd, "AMB2: void family " + spec["name"]); t.Start()
        try:
            for e in list(FilteredElementCollector(fd).OfClass(GenericForm)):
                try: fd.Delete(e.Id)
                except: pass
            fd.Regenerate()
            sp = SketchPlane.Create(fd, Plane.CreateByNormalAndOrigin(XYZ.BasisY, XYZ.Zero))
            segs = arch_loops(spec["w"], spec["h"], spec["shape"], spec.get("rise", 0.0), spec.get("d", 0.0), 0.0)
            ca = CurveArray()
            for s in segs:
                if s[0] == "L": ca.Append(Line.CreateBound(XYZ(s[1][0] / FT, 0, s[1][1] / FT), XYZ(s[2][0] / FT, 0, s[2][1] / FT)))
                else: ca.Append(Arc.Create(XYZ(s[1][0] / FT, 0, s[1][1] / FT), XYZ(s[3][0] / FT, 0, s[3][1] / FT), XYZ(s[2][0] / FT, 0, s[2][1] / FT)))
            arr = CurveArrArray(); arr.Append(ca)
            depth = spec.get("depth", 0.7)
            ex = fd.FamilyCreate.NewExtrusion(False, arr, sp, depth / FT)
            ex.StartOffset = -depth / 2.0 / FT; ex.EndOffset = depth / 2.0 / FT
            t.Commit()
        except Exception as e:
            t.RollBack(); raise
        class Opt(IFamilyLoadOptions):
            def OnFamilyFound(self, inUse, overwrite): return True
            def OnSharedFamilyFound(self, shared, inUse, source, overwrite): return True
        so = SaveAsOptions(); so.OverwriteExistingFile = True
        fd.SaveAs(System.IO.Path.Combine(System.IO.Path.GetTempPath(), spec["name"] + ".rfa"), so)
        return fd.LoadFamily(doc, Opt())
    finally:
        fd.Close(False)

# ---- arch families are created first (EditFamily cannot run inside a transaction of the project) ----
def _wh(o, is_door): return (o.get("w_mm") or int(round(o["width"] * SC * 1000.0 / 50) * 50), o.get("h_mm") or (2100 if is_door else 1250))
need = {}
for (o, is_door) in [(d, True) for d in DATA["doors"]] + [(w, False) for w in DATA["windows"]]:
    if o.get("shape"):
        w_mm, h_mm = _wh(o, is_door)
        fname = "AMB2_%s_%s_%dx%d" % ("Door" if is_door else "Win", o["shape"], w_mm, h_mm)
        need[fname] = dict(name=fname, kind="door" if is_door else "window", w=w_mm / 1000.0, h=h_mm / 1000.0, shape=o["shape"], rise=o.get("rise_mm", 0) / 1000.0, d=o.get("d_mm", 0) / 1000.0 or 0.12 * w_mm / 1000.0, leaf_h=o.get("leaf_h_mm", 2150) / 1000.0, depth=0.32)
def _drop_arch_families():
    for f in list(FilteredElementCollector(doc).OfClass(Family)):
        if f.Name.startswith(("AMB2_Win_", "AMB2_Door_", "AMB2_Test_", "AMB2_Void_")):
            try: doc.Delete(f.Id)
            except Exception as ex: say("could not delete family %s: %s" % (f.Name, ex))
if DATA.get("purge", True): run("AMB2: drop old arch families", _drop_arch_families)      # always regenerate them: geometry fixes must reach the model
have = set(x.Name.lower() for x in FilteredElementCollector(doc).OfClass(Family))
for fname in need:
    if fname.lower() in have: continue
    try:
        make_family(need[fname]); say("family created: " + fname)
        vs = dict(need[fname]); vs["name"] = fname.replace("AMB2_Win_", "AMB2_Void_").replace("AMB2_Door_", "AMB2_Void_")
        make_void_family(vs); say("void family created: " + vs["name"])
    except Exception as e:
        say("FAMILY FAILED %s: %s" % (fname, e))

def walls_by_mark():
    out = {}
    for w in FilteredElementCollector(doc).OfClass(Wall):
        m = w.get_Parameter(BuiltInParameter.ALL_MODEL_MARK).AsString()
        c = cmt(w)
        if m and c and c.startswith(TAG + "p3_walls"): out[(c.split(":")[1], m)] = w
    return out
WALLS = walls_by_mark()
def wall_of(mark):
    for (ph, m), w in WALLS.items():
        if m == mark: return w

def base_symbol(cat, fam):
    for s in FilteredElementCollector(doc).OfCategory(cat).WhereElementIsElementType():
        if s.FamilyName == fam: return s

def sized_type(cat, fam, prefix, w_mm, h_mm, o=None):
    shape = o.get("shape") if o else None
    if shape:
        # arched opening: a dedicated family generated by p8 (the geometry is fixed, so size is part of the name)
        fname = "AMB2_%s_%s_%dx%d" % ("Door" if cat == BuiltInCategory.OST_Doors else "Win", shape, w_mm, h_mm)
        f = [x for x in FilteredElementCollector(doc).OfClass(Family) if x.Name.lower() == fname.lower()]
        if not f: raise Exception("arch family %s is not loaded" % fname)
        sym = doc.GetElement(list(f[0].GetFamilySymbolIds())[0])
        if not sym.IsActive: sym.Activate()          # never edit Width/Height here: it rescales the family's geometry
        return sym
    name = "%s_%dx%d" % (prefix, w_mm, h_mm)
    for s in FilteredElementCollector(doc).OfCategory(cat).WhereElementIsElementType():
        if s.get_Parameter(BuiltInParameter.SYMBOL_NAME_PARAM).AsString() == name: return s
    b = base_symbol(cat, fam)
    t = b.Duplicate(name)
    for pn, v in (("Width", w_mm), ("Height", h_mm)):
        p = t.LookupParameter(pn)
        if p is not None and not p.IsReadOnly: p.Set(v / 304.8)
    try:
        if not t.IsActive: t.Activate()
    except: pass
    return t

def round_mm(v, step=10): return int(round(v / step) * step)
SC_MM = SC * 1000.0
placed = []
skipped = []
hostv0 = {}
def place_one(o, is_door):
    host = wall_of(o["wall"])
    if host is None: say("NO HOST %s %s" % (o["id"], o["wall"])); return
    lvl = level_named(o["level"]) if o.get("level") else doc.GetElement(host.get_Parameter(BuiltInParameter.WALL_BASE_CONSTRAINT).AsElementId())   # o["level"]: place on another level than the wall base (door onto the roof)
    w_mm = o.get("w_mm") or round_mm(o["width"] * SC_MM, 50)
    h_mm = o.get("h_mm") or (2100 if is_door else 1250)
    try:
        if is_door:
            t = sized_type(BuiltInCategory.OST_Doors, "M_Single-Flush", "AMB2_Door", w_mm, h_mm, o)
        else:
            t = sized_type(BuiltInCategory.OST_Windows, "M_Fixed", "AMB2_Window", w_mm, h_mm, o)
    except Exception as ex:
        say("NO TYPE for %s: %s" % (o["id"], ex)); skipped.append(o["id"]); return
    if not t.IsActive: t.Activate(); doc.Regenerate()
    pt = P(o["x"], o["y"], 0); loc = XYZ(pt.X, pt.Y, lvl.Elevation)
    crv = host.Location.Curve
    pr = crv.Project(XYZ(pt.X, pt.Y, crv.GetEndPoint(0).Z))
    along = pr.XYZPoint.DistanceTo(crv.GetEndPoint(0)) * FT; L = crv.Length * FT
    half = w_mm / 2000.0
    if along - half < 0.03 or along + half > L - 0.03 or pr.Distance * FT > 0.3:
        say("DOES NOT FIT %s in wall %s: centre %.2f m along a %.2f m wall, half width %.2f m, off the wall by %.2f m" % (o["id"], o["wall"], along, L, half, pr.Distance * FT))
        skipped.append(o["id"]); return
    v0 = host.get_Parameter(BuiltInParameter.HOST_VOLUME_COMPUTED).AsDouble()
    hostv0.setdefault(host.Id.IntegerValue, v0)
    fi = doc.Create.NewFamilyInstance(loc, t, host, lvl, Structure.StructuralType.NonStructural)
    tag(fi, PH); fi.get_Parameter(BuiltInParameter.ALL_MODEL_MARK).Set(o["id"])
    if not is_door:
        p = fi.get_Parameter(BuiltInParameter.INSTANCE_SILL_HEIGHT_PARAM)
        if p is not None and not p.IsReadOnly: p.Set(o.get("sill_mm", 1050) / 304.8)
    placed.append((o, fi, host, v0, is_door))
    if o.get("shape"):
        vname = "AMB2_%s_%s_%dx%d" % ("Void", o["shape"], w_mm, h_mm)
        vf = [x for x in FilteredElementCollector(doc).OfClass(Family) if x.Name.lower() == vname.lower()]
        if not vf: say("NO VOID FAMILY " + vname); return
        vs_ = doc.GetElement(list(vf[0].GetFamilySymbolIds())[0])
        if not vs_.IsActive: vs_.Activate(); doc.Regenerate()
        base_z = lvl.Elevation + (0.0 if is_door else o.get("sill_mm", 1050) / 304.8)
        vi = doc.Create.NewFamilyInstance(XYZ(pt.X, pt.Y, base_z), vs_, lvl, Structure.StructuralType.NonStructural)
        crv_ = host.Location.Curve; dv = (crv_.GetEndPoint(1) - crv_.GetEndPoint(0)).Normalize()
        ang = math.atan2(dv.Y, dv.X)
        if abs(ang) > 1e-6:
            ElementTransformUtils.RotateElement(doc, vi.Id, Line.CreateBound(XYZ(pt.X, pt.Y, base_z), XYZ(pt.X, pt.Y, base_z + 1.0)), ang)
        tag(vi, PH); vi.get_Parameter(BuiltInParameter.ALL_MODEL_MARK).Set("V_" + o["id"])
        try:
            InstanceVoidCutUtils.AddInstanceVoidCut(doc, host, vi)
        except Exception as ex_:
            say("VOID CUT FAILED %s: %s" % (o["id"], ex_))

ITEMS = [(d, True) for d in DATA["doors"]] + [(w, False) for w in DATA["windows"]]
if DATA.get("ids"): ITEMS = [(o, d) for (o, d) in ITEMS if o["id"] in DATA["ids"]]       # chunked runs stay under the 30 s bridge timeout
# One transaction per opening: windows placed together in one big transaction were left uncut in several walls (measured with
# rays), while the same window placed in its own transaction cut the wall.
for (_o, _d) in ITEMS:
    run("AMB2: opening " + _o["id"], lambda _o=_o, _d=_d: place_one(_o, _d))

# ---- door swing: make hinge side and swing side match the drawing (arcs read from the DWG) ----
def plan_view_for(host):
    lvl = doc.GetElement(host.get_Parameter(BuiltInParameter.WALL_BASE_CONSTRAINT).AsElementId())
    for v in FilteredElementCollector(doc).OfClass(ViewPlan):
        if not v.IsTemplate and v.GenLevel is not None and v.GenLevel.Id == lvl.Id and v.get_Parameter(BuiltInParameter.VIEW_NAME).AsString().startswith("AMB2"):
            return v

def swing_arc(fi, view):
    opt = Options(); opt.View = view
    ge = fi.get_Geometry(opt)
    if ge is None: return None
    for g in ge:
        if isinstance(g, GeometryInstance):
            for h in g.GetInstanceGeometry():
                if isinstance(h, Arc) and h.Radius * FT > 0.25: return h
        elif isinstance(g, Arc) and g.Radius * FT > 0.25: return g
    return None

def fix_swings():
    for (o, fi, host, v0, is_door) in placed:
        if not is_door or "hinge" not in o: continue
        view = plan_view_for(host)
        want_h = P(o["hinge"][0], o["hinge"][1], 0); want_m = P(o["swing_pt"][0], o["swing_pt"][1], 0)
        for attempt in range(4):
            doc.Regenerate()
            arc = swing_arc(fi, view)
            if arc is None: say("swing %s: no swing arc found in %s" % (o["id"], view.Name if view else None)); break
            c = arc.Center; m = arc.Evaluate(0.5, True)
            loc = fi.Location.Point
            n = host.Orientation
            side_ok = ((m - loc).DotProduct(n)) * ((want_m - loc).DotProduct(n)) > 0
            hinge_ok = c.DistanceTo(XYZ(want_h.X, want_h.Y, c.Z)) < 0.45 * (o.get("w_mm", 900) / 304.8)
            if side_ok and hinge_ok: break
            if not side_ok: fi.flipFacing()
            else: fi.flipHand()
        else:
            say("swing %s: could not match after 4 flips" % o["id"])
run("AMB2: door swings " + PH, fix_swings)

bad = 0
try:
    per = {}
    for (o, fi, host, v0, is_door) in placed:
        per.setdefault(host.Id.IntegerValue, (host, []))[1].append((o, is_door))
    for hid in per:
        host, os_ = per[hid]
        cut = (hostv0[hid] - host.get_Parameter(BuiltInParameter.HOST_VOLUME_COMPUTED).AsDouble()) * 0.0283168
        t = host.Width * FT
        exp = sum([(o.get("w_mm") or round_mm(o["width"] * SC_MM, 50)) / 1000.0 * ((o.get("h_mm") or (2100 if d else 1250)) / 1000.0) * t for (o, d) in os_])
        ok = cut > 0.5 * exp
        if not ok: bad += 1
        say("wall %-5s %d openings %-28s cut %.3f m3 (expected ~%.3f) %s" % (cmt(host).split(":")[1][:8] if False else doc.GetElement(host.Id).get_Parameter(BuiltInParameter.ALL_MODEL_MARK).AsString(), len(os_), ",".join([o["id"] for (o, d) in os_]), cut, exp, "OK" if ok else "CHECK"))
    say("openings placed %d, walls needing a check %d" % (len(placed), bad))
except Exception as e:
    say("verification failed: %s" % e)
__output__ = chr(10).join(LOG)
